INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0ff1501a-a930-456e-b96b-fc7a2ec81d23', 'Percentage Rent', '1', NULL, 'RENTA VARIABLE', E'- Se añade una cláusula de Renta Variable al contrato de arrendamiento.\n- Renta Mensual fija: $400,622.25 más IVA.\n- Renta Variable: 8% de las Ventas Netas Mensuales del arrendatario en el local.\n- El arrendatario debe pagar la mayor cantidad entre la Renta Mínima Mensual y la Renta Variable.\n- El arrendatario debe enviar un reporte mensual de Ventas Netas dentro de los primeros 10 días del mes.\n- Si no se entrega el reporte, se paga una penalización diaria de un día de renta mínima.\n- Si la Renta Variable supera la Renta Mínima, la diferencia se paga en los primeros 5 días del mes siguiente.\n- La arrendadora tiene 30 días para objetar el reporte mensual, salvo excepciones como errores fiscales o fraudes.\n- Omisiones en el reporte deben corregirse en 3 días, o se aplican intereses del 2% mensual.\n- Ventas Netas Mensuales se calculan restando impuestos, devoluciones, comisiones, y otros descuentos de las Ventas Brutas.', E'Las partes convienen en adicionar a la CARATULA el apartado 11.1.- Renta Variable, del CONTRATO DE ARRENDAMIENTO, con lo cual, a partir de la fecha de firma de este instrumento, la declaración quedará redactada en los términos que a continuación se indican, teniéndose como si se insertase a la letra y surtiendo todos sus efectos: \nA) Renta Mensual: La cantidad mensual de $400,622.25M.N. (cuatrocientos mil seiscientos veintidós pesos 25/100 moneda nacional) más el impuesto al valor agregado.\nB) Renta Variable: Pagará el 8% (ocho por ciento) de Las Ventas Netas Mensuales que obtenga, perciba, registre o cualquier tipo de ingreso, atribuible a "LA ARRENDATARIA" en el Local arrendado durante el mes de que se trate.\n\nPRIMERA. - OBJETO Y RENTA. - El objeto del presente Contrato es el otorgamiento del uso y goce del Local Comercial por parte de la Arrendadora en favor de la Arrendataria, quien toma en arrendamiento el Local Comercial.\n"LA ARRENDATARIA" se obliga incondicional e irrevocablemente a pagar a "LA ARRENDADORA", por concepto de Renta Mensual (Renta), la cantidad que resulte mayor entre una Renta denominada Renta Mínima Mensual señalada en el apartado 11.- de la Caratula, en el entendido que cualquier diferencia en la superficie, mayor o menor a un 5% (cinco por ciento) dará derecho a modificar los términos económicos pactados en el presente Contrato, en la misma proporción en que haya variado dicha superficie y la cantidad que resulte de aplicar a Las Ventas Netas Mensuales el porcentaje señalado en el apartado 11.1 de la Caratula, de conformidad con lo siguiente:\n"LA ARRENDATARIA" se obliga a entregar a "LA ARRENDADORA" dentro de los primeros 10 (diez) días naturales del mes, un reporte mensual bajo protesta de decir verdad del que se desprenda el importe real y verdadero de las Ventas Netas Mensuales sobre las que se calculará el importe de la Renta Variable a pagar de que se trate, mismo que deberá ser enviado a la dirección de correo siguiente: reportedeventas@alteadesarrollos.com. En caso de que "LA ARRENDATARIA"no entregue dicho reporte, por concepto de Renta Variable y en adición a la Renta Minima Mensual, deberá pagar a "LA ARRENDADORA" el monto correspondiente a 1 (un) dia de la renta mínima que este vigente al momento del incumplimiento, por cada día de atraso en el cumplimiento de la obligación de entregar el Reporte de ventas, cantidad que deberá ser cubierta los primeros 10 (diez) días del mes siguiente al que corresponda, sin requerir notificación previa, si transcurridos 60(sesenta) días contados a partir de la fecha en que la Arrendataria debió de entregar el Reporte de ventas "LA ARRENDADORA” si así lo considera podrá demandar la recisión del presente Contrato.\n\nSi como consecuencia de la aplicación en un mes determinado, en el Local arrendado, de los porcentajes antes señalados sobre las Ventas Netas Mensuales realizadas por "LA ARRENDATARIA" y con base en el reporte mensual que ésta remita, resultara una cantidad superior a la Renta Mínima Mensual, la diferencia deberá ser pagada por "LA ARRENDATARIA" dentro de los primeros 5 (cinco) días naturales del mes siguiente al que corresponde el pago de las Rentas, contra la entrega de la factura o el CFDI correspondiente que será enviado a la siguiente dirección de correo electrónico: fpt_arrendamiento@fpt.com.mx. Queda establecido que, si la Renta Mínima Mensual fuese mayor que la que resulte de aplicar los porcentajes acordados, aquella quedará como cumplimiento de esta obligación (pago definitivo), no teniendo "LA ARRENDADORA" obligación de devolver cantidad alguna.\n\nEn caso de que "LA ARRENDADORA" no objete el reporte mensual que hubiere recibido, dentro de los 30 (treinta) días naturales siguientes a su recepción, se entenderá que lo acepta y no podrá objetarlo posteriormente, excepto: i) en los casos que exista una declaración complementaria normal o por dictamen fiscal o una revisión de cualquier autoridad fiscal competente que determine alguna omisión de ingresos y ii) en el caso de que al compulsar los ingresos manifestados por "LA ARRENDATARIA" mensualmente, éstos no concuerden con su declaración anual en el Impuesto Sobre la Renta debidamente presentada y iii) en los casos de desvío de fondos o fraudes, abusos de confianza que "LA ARRENDATARIA" instaure u obtenga por acciones intentadas.\n\nn caso de que "LA ARRENDATARIA" omita algún ingreso de sus Ventas Netas Mensuales, cubrirá la cantidad que haya omitido más el IVA, dentro de los siguientes 3 (tres) días naturales de que se haya detectado dicha omisión y sino la paga en ese término causará intereses moratorios al 2% (dos por ciento) por cada mes o fracción de éste, hasta su total conclusión.\nPara los efectos de este Contrato se entenderá por Ventas Netas Mensuales, las que "LA ARRENDATARIA" realice durante cada mes calendario en el Local arrendado que instalará y operará en el Centro Comercial las ventas netas mensuales quedarán constituidas por el importe que se obtenga de restar a las Ventas Brutas (es decir, al importe total de las ventas efectuadas): i) los impuestos sobre las ventas, ii) las cancelaciones, devoluciones, bonificaciones, iii) comisiones Bancarias o a terceros y los descuentos sobre las mismas, iv) la venta de activos fijos de "LA ARRENDATARIA", v) la venta de artículos de promoción y vi) la venta de membresías. En la inteligencia de que no se considerarán como parte de las Ventas Netas las remesas de mercancía que se efectúen entre las diferentes tiendas de "LA ARRENDATARIA", ni los impuestos vigentes o futuros sobre la venta de mercancías.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0ff1501a-a930-456e-b96b-fc7a2ec81d23', 'Common Area Maintenance Charges', '2', 'Carátula', NULL, '- 12% plus Value Added Tax (VAT)', '12% (doce por ciento) más Impuesto al Valor Agregado');
