rand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2026-06-01 20:11:43","active_lease_count_over_time":61538,"location_count_over_time":68151,"remaining_rent_liability_over_time":61538}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', '79c8c753-28e1-4663-a6ce-5e6a78c7efc4', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Oaxaca Santa Rosa Sublease: Inmobiliaria Kira, S.A. de C.V.', NULL, true, 'activo', 'Lease', NULL, NULL, NULL, NULL, NULL, false, 1, NULL, 0, NULL, NULL, NULL, 'Send Notice to Renew', NULL, 'Inmobiliaria Kira, S.A. de C.V.', NULL, NULL, 'Avenida Constituyentes 1150', NULL, 'Lomas Altas, Miguel Hidago', 'Ciudad de México', '11950', 'MX', NULL, NULL, NULL, 120, NULL, NULL, NULL, 726050.7, 'La subarrendataria deberá pagar al subarrendador, en la fecha de entrega del local, un monto equivalente a dos meses de renta ($726,050.70 más IVA). Este pago se aplicará a los primeros dos meses de renta, una vez concluido el plazo de gracia o desde que inicie operaciones el negocio, lo que ocurra primero.', NULL, true, '{"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"is_next_percent_rent_payment":"No","rent_commencement_date_original":"TBD","expiration_date_original":"TBD","expiration_date_including_options_original":"TBD"}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Domicilio del Contrato', '"Oaxaca Santa Rosa" con domicilio en la Fracción Uno del Lote conocido sin número, Agencia Municipal de Santa Rosa Panzacola, Oaxaca de Juárez, Centro Oaxaca.', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Fecha de Firma del Contrato', '02 de marzo de 2026', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Plazo', '10 años forzosos para ambas partes contados a partir de la Fecha de Entrega Efectiva del Local comercial', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'fecha de inicio de pago de renta', 'A partir del vencimiento del Plazo de Gracia, o bien en la fecha que LA ARRENDATARIA inicie operaciones del NEGOCIO que será instalado en EL LOCAL COMERCIAL, lo que suceda primero', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Fecha de entrega del local comercial', 'Las Partes aceptan que la entrega-recepción de la posesión en calidad de subarrendamiento de EL LOCAL COMERCIAL para lo cual se le notificara a LA SUBARRENDATARIA con al menos 30 (treinta) días previos a la fecha de entrega (en lo sucesivo la "Entrega Programada").', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Extension period', '7', 'Cuarta', 'PLAZO', E'- The tenant can extend the lease for an additional 5 years.\n- The tenant must notify the landlord at least 180 days before the current lease ends.\n- The financial terms of the extension will be negotiated between the tenant and landlord.\n- Any rent increase cannot be more than 12.5% of the current minimum rent.', 'La arrendataria tiene derecho a prorrogar el contrato por 5 años adicionales, notificando al arrendador con al menos 180 días de anticipación, las condiciones económicas de la prórroga se negociarán entre las partes, y cualquier incremento en la renta no podrá exceder el 12.5% de la última Renta Mínima vigente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Base Rent', '8', 'Sexta', 'IMPORTE DE LA RENTA DEL LOCAL COMERCIAL', E'- The tenant must start paying rent after the grace period ends or when they begin operations, whichever comes first.\n- The rent will be the higher amount between:\n  - A fixed minimum rent of $363,025.35 plus VAT, or\n  - 5% of their monthly net income plus VAT (variable rent).', 'La arrendataria deberá pagar, a partir del fin del plazo de gracia o desde que inicie operaciones (lo que ocurra primero), la cantidad que resulte mayor entre; Una renta mínima fija de $363,025.35 más IVA, o El 5% de sus ingresos netos mensuales más IVA (renta variable).');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Common Area Maintenance Charges', '9', 'Séptima', 'CUOTA DE MANTENIMIENTO', E'- The tenant must pay a monthly Maintenance Fee.\n- This fee is 15% of the minimum monthly rent.\n- Value Added Tax (IVA) is added to this fee.', 'La arrendataria deberá pagar mensualmente una Cuota de Mantenimiento equivalente al 15% de la renta mínima mensual más IVA');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Incremento de Renta', '8', 'Sexta', 'IMPORTE DE LA RENTA DEL LOCAL COMERCIAL', E'- The rent will be adjusted annually.\n- The adjustment is based on the increase in the National Consumer Price Index (INPC).\n- The INPC is published by INEGI.\n- The adjustment considers the variation over the last 12 months.', 'La renta se ajustará anualmente conforme al incremento del Índice Nacional de Precios al Consumidor (INPC) publicado por el INEGI, considerando la variación de los últimos 12 meses.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Late Fees', '9', 'Octava', 'FORMA Y LUGAR DE PAGO DE RENTA', E'- Late interest is calculated using the 28-day TIIE rate multiplied by 3.\n- This interest applies from the due date until the debt is fully paid.', 'Intereses moratorios calculados con base en la TIIE a 28 días multiplicada por 3, desde la fecha en que debió pagarse hasta que se liquide totalmente el adeudo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Parking', '10', 'Novena', 'OBLIGACIONES DEL ARRENDADOR', E'- Si el centro comercial cobra por estacionamiento, la arrendataria recibirá algunos lugares gratuitos para su personal.\n- Los demás empleados, clientes y visitantes deben pagar la tarifa regular.\n- Los clientes de la arrendataria pagarán una tarifa preferencial de hasta $10 por las primeras 2 horas; después se aplicará la tarifa normal.\n- La tarifa preferencial puede actualizarse cada 24 meses si hay aumentos generales en el centro comercial.', E'Si el centro comercial cobra estacionamiento, las partes acordarán otorgar a la arrendataria cierto número de lugares gratuitos (pensiones o cortesías) para su personal, mientras que el resto de empleados, clientes y visitantes deberán pagar la tarifa vigente.\nAdemás, se otorgará a los clientes de la arrendataria una tarifa preferencial de hasta $10 por las primeras 2 horas; después de ese tiempo aplicará la tarifa normal.\nEsta tarifa preferencial podrá actualizarse cada 24 meses, siempre que haya incrementos generales en el centro comercial.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('018d9881-46dc-4e85-8a76-6de326ae91a9', 'Período para obtener licencias y permisos', '13', 'Décima Primera', 'DERECHOS DE LA ARRENDATARIA', E'- If the tenant doesn''t get the necessary permits, licenses, or services within 120 days after taking possession of the premises, and it''s not their fault, they can:\n  - End the lease without penalty, and the landlord must refund any payments made.\n  - Agree to an additional 120 days to obtain the permits.\n\n- This is valid if the tenant proves they made the necessary efforts and the lack of permits isn''t their fault.\n\n- Once the landlord is notified, they have up to 60 days to try to obtain the required permits or services.', E'Si dentro de los 120 días posteriores a la entrega del local la arrendataria no obtiene los permisos, licencias o servicios necesarios por causas no imputables a ella, podrá: i) Dar por terminado el contrato sin responsabilidad, obligándose el arrendador a devolver las cantidades pagadas, o\nii) Acordar un plazo adicional de 120 días para obtenerlos.\n\nEsto aplica siempre que la arrendataria demuestre que realizó las gestiones necesarias y que la falta de permisos no es imputable a ella. Adicionalmente, una vez notificado el arrendador, este contará con hasta 60 días para intentar obtener dichos permisos o servicios requeridos.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('a2e74b19-b52b-430f-ada0-acadc3110334', 'Xalapa Américas', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '680 Carretera Federal Xalapa-Veracruz Km 2.5', NULL, 'Xalapa', 'Veracruz', '0000', 'MX', '680 Carretera Federal Xalapa-Veracruz Km 2.5,  Xalapa, Veracruz 0000', 19.5124397603, -96.8771809567, 'Retail', 'Lifestyle Center', 'Fitness', NULL, 'Plaza Las Américas, Xalapa', 2000, NULL, NULL, '{"map_marker_color":"#808080","coordinate":"point|19.5124397603|-96.8771809567|accurate","city_state":"Xalapa, Veracruz","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"Avenida Constituyentes 1150, Lomas Altas, Miguel Hidalgo, Ciudad de México 11950","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"TBD","lease_expiration_date":"TBD","lease_renewal_notice":"180 Days Prior","lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":68169,"grid_name":"Xalapa Américas","grid_full_address":"680 Carretera Federal Xalapa-Veracruz Km 2.5,  Xalapa, Veracruz 0000","map_addr_1":"680 Carretera Federal Xalapa-Veracruz Km 2.5","map_city_state_zip":"Xalapa, Veracruz 0000","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2026-06-01 22:49:36","active_lease_count_over_time":61543,"location_count_over_time":68169,"remaining_rent_liability_over_time":61543}'::jsonb);
