INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Fecha de Firma del Contrato', '02 de marzo 2026', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Vigencia', 'El plazo del arrendamiento será de 10 (diez) años forzosos para ambas partes contados a partir de la fecha de Fecha de Entrega Efectiva de EL LOCAL COMERCIAL.', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Fecha de entrega del Local comercial', 'Las Partes aceptan que la entrega-recepción de la posesión en calidad de arrendamiento de EL LOCAL COMERCIAL para lo cual se le notificara a LA ARRENDATARIA con al menos 30 (treinta) días previos a la fecha de entrega (en lo sucesivo la "Entrega Programada").', 'America Gonzalez', NULL);
